import json
from pathlib import Path
p=Path(__file__).parent/'data/narratives.json';a=json.loads(p.read_text(encoding='utf8'))
a[0]+='\n\nОпись также содержит правила чтения контрольных вопросов. Утвердительная форма вопроса не является дополнительным свидетельством. Если спрашивается, произошло ли действие после другого, нужно проверить именно указанный порядок, а не просто найти оба события. Отрицательный ответ на такую формулировку может быть полностью доказан. В эталонной таблице он обозначается как опровержение проверяемой пропозиции, а не как отсутствие данных. Это различие необходимо сохранить при оценке: модель, которая отвечает уверенным отрицанием при наличии обратного порядка, выполняет другую операцию, чем модель, которая отказывается из-за отсутствия времени. Секретарь просит не смешивать эти результаты в общей колонке «нет». Для конфликтующих источников предусмотрена отдельная категория с двумя наборами ссылок.'
p.write_text(json.dumps(a,ensure_ascii=False,indent=2),encoding='utf8')
